1: #version 300 es
2:   precision highp float;
3: 
4:   uniform float u_aspectRatio;
5:   uniform vec3 u_cameraPos;
6:   uniform float u_fov;
7:   uniform vec3 u_pointing;
8:   
9:   uniform float u_time;
10:   uniform float u_eps;
11: 
12:   in vec2 uv;
13:   out vec4 fragColor;
14: 
15:   vec3 refraction(vec3 ray, vec3 norm, float r) {
16:     norm = normalize(norm);
17:     ray = normalize(ray);
18:     
19:     float d = dot(norm, ray);
20:     float k = 1.0 - r*r*(1.0-d*d);
21:     
22:     if (k > 0.) {
23:         return r * ray - (r * d + sqrt(k)) * norm;
24:     }
25:     
26:     return ray - 2.0 * d * norm;
27:   }
28: 
29: 
30: 
31:   float opDisplacement(vec3 rayPos) {
32:     return sin(rayPos.x * 2.13) * sin(rayPos.y * 4.1) * sin(rayPos.z * 3.1);
33:   }
34: 
35:   vec3 opTwist(vec3 p, float k) {
36:     float c = cos(k*p.y);
37:     float s = sin(k*p.y);
38:     return vec3( mat2(c, -s, s, c) * p.xz, p.y);
39:   }
40: 
41: 
42:   float sdSphere(vec3 rayPos, vec3 spherePos, float r) {
43:     return length(rayPos - spherePos) - r;
44:   }
45: 
46:   float sdBox( vec3 rayPos, vec3 b ) {
47:     vec3 q = abs(rayPos) - b;
48:     return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
49:   }
50: 
51:   float sdCappedCylinder( vec3 p, float r, float h )
52:   {
53:     vec2 d = abs(vec2(length(p.xy), p.z)) - vec2(r,h);
54:     return min(max(d.x,d.y),0.0) + length(max(d,0.0));
55:   }
56: 
57:   
58:   vec3 rotate(vec3 p, vec3 r) {
59:     vec3 s = sin(r);
60:     vec3 c = cos(r);
61:     // vec3 s = vec3(sin(r.x), sin(r.y), sin(r.z));
62:     // vec3 c = vec3(cos(r.x), cos(r.y), cos(r.z));
63: 
64:     return p * mat3(
65:       1., 0., 0.,
66:       0., c.x, -s.x,
67:       0., s.x, c.x
68:     ) * mat3(
69:       c.y, 0., s.y,
70:       0., 1., 0.,
71:       -s.y, 0., c.y
72:     ) * mat3(
73:       c.z, -s.z, 0.,
74:       s.z, c.z, 0.,
75:       0., 0., 1.
76:     );
77:   }
78: 
79:   float getDist(vec3 rayPos) {
80:     vec3 p = rotate(rayPos, vec3(sin(u_time), u_time*0.8, u_time*1.51) );
81:     
82:     return sdBox(
83:       p,
84:       vec3(2.0)
85:     ) - 0.5;
86:   }
87: 
88:   vec3 getNormal(vec3 rayPos) {
89:     const vec2 k = vec2(1, -1);
90:     
91:     vec3 norm = k.xyy * getDist(rayPos + k.xyy*u_eps) +
92:                 k.yxy * getDist(rayPos + k.yxy*u_eps) +
93:                 k.xxx * getDist(rayPos + k.xxx*u_eps) +
94:                 k.yyx * getDist(rayPos + k.yyx*u_eps);
95:                 
96:     return normalize(norm);
97:   }
98:   
99:   void main() {
100:     vec3 reference = normalize(u_pointing - u_cameraPos);
101: 
102:     vec3 horizontal = cross(reference, vec3(0.0, 0.0, 1.0)); // z vector is up
103:     vec3 vertical = cross(horizontal, reference);
104: 
105:     horizontal = normalize(horizontal) * tan(radians(u_fov) / 2.0);
106:     vertical = normalize(vertical) * tan(radians(u_fov) / 2.0) / u_aspectRatio;
107: 
108:     vec3 cameraRay = normalize(reference + (uv.x - 0.5) * 2.0 * horizontal + (uv.y - 0.5) * 2.0 * vertical);
109: 
110:     vec3 rayPos = u_cameraPos;
111:     vec3 rayDir = cameraRay;
112:     float totalDistance = 0.0;
113:     
114:     
115:     for (int i = 0; i < 512; i++) {
116:       float distance = getDist(rayPos);
117: 
118:       totalDistance += distance;
119:       rayPos += rayDir * distance;
120: 
121: 
122:       // Hits the face
123:       if (abs(distance) < 0.00001) {
124:         vec3 normal = getNormal(rayPos);
125:         float IOR = 1.3;
126: 
127:         rayDir = refraction(rayDir, normal, distance > 0.0 ? IOR : 1.0/IOR);
128:         rayPos += rayDir * 0.1; // Helper
129:       }
130: 
131: 
132:       if (totalDistance > 1000.0) {
133:         break;
134:       }
135:     }
